    function cast(bytes32 ciphertext, FheType toType) internal returns (bytes32 result) {
        FHEVMConfigStruct storage $ = getFHEVMConfig();
        result = IFHEVMExecutor($.FHEVMExecutorAddress).cast(ciphertext, toType);
