    function getSepoliaConfig() internal pure returns (FHEVMConfigStruct memory) {
        return
            FHEVMConfigStruct({
                ACLAddress: 0x50157CFfD6bBFA2DECe204a89ec419c23ef5755D,
                FHEVMExecutorAddress: 0xCD3ab3bd6bcc0c0bf3E27912a92043e817B1cf69,
